import { createHash } from 'node:crypto';
import { readFile } from 'node:fs/promises';
import { relative, resolve } from 'node:path';

export const archiveSchemaVersion = 'workduck.ssealed-scaffold-archive/v1';
export const scaffoldDensity = 'standard';
export const scaffoldRunner = 'none';

export function renderGeneratedRust({ version, archiveChecksum }) {
	return [
		'// @generated by scripts/sync-ssealed-scaffold.mjs --write. Do not edit by hand.',
		'',
		`pub const SSEALED_SCAFFOLD_ARCHIVE_SCHEMA_VERSION: &str = ${JSON.stringify(archiveSchemaVersion)};`,
		`pub const SSEALED_SCAFFOLD_TOOL_VERSION: &str = ${JSON.stringify(version)};`,
		`pub const SSEALED_SCAFFOLD_ARCHIVE_SHA256: &str = ${JSON.stringify(archiveChecksum)};`,
		'pub const SSEALED_SCAFFOLD_ARCHIVE_JSON: &str =',
		'\tinclude_str!("../resources/ssealed-scaffolds-v1.json");',
		''
	].join('\n');
}

export function renderGeneratedTypeScript({ scopes, profiles }) {
	return [
		'// @generated by scripts/sync-ssealed-scaffold.mjs --write. Do not edit by hand.',
		'',
		`export const SSEALED_SCAFFOLD_SCOPES = ${JSON.stringify(scopes, null, '\t')} as const;`,
		'',
		`export const SSEALED_SCAFFOLD_PROFILES = ${JSON.stringify(profiles, null, '\t')} as const;`,
		''
	].join('\n');
}

export async function assertCurrentArtifact(repositoryRoot, path, expected) {
	let current;
	try {
		current = await readFile(path, 'utf8');
	} catch (error) {
		throw new Error(`${relative(repositoryRoot, path)} is missing; run bun run sync:ssealed-scaffold.`, { cause: error });
	}
	if (current !== expected) {
		throw new Error(`${relative(repositoryRoot, path)} is stale; run bun run sync:ssealed-scaffold.`);
	}
}

export async function verifyEmbeddedSsealedArtifacts(repositoryRoot, { version, scopes, profiles }) {
	const archivePath = resolve(repositoryRoot, 'src-tauri/resources/ssealed-scaffolds-v1.json');
	const rawArchive = await readFile(archivePath, 'utf8');
	const archive = JSON.parse(rawArchive);
	const repair = 'Run bun run sync:ssealed-scaffold.';
	if (archive.schemaVersion !== archiveSchemaVersion || archive.toolVersion !== version ||
		archive.density !== scaffoldDensity || archive.runner !== scaffoldRunner) {
		throw new Error(`Embedded ssealed scaffold metadata does not match installed ssealed ${version}. ${repair}`);
	}
	const expected = new Set(scopes.flatMap((scope) => profiles.map((profile) => `${scope}\0${profile}`)));
	if (!Array.isArray(archive.scaffolds) || archive.scaffolds.length !== expected.size) {
		throw new Error(`Embedded ssealed scaffold selections are incomplete. ${repair}`);
	}
	for (const scaffold of archive.scaffolds) {
		if (!expected.delete(`${scaffold.scope}\0${scaffold.profile}`) ||
			!Array.isArray(scaffold.files) || scaffold.files.length === 0) {
			throw new Error(`Embedded ssealed scaffold selections are invalid. ${repair}`);
		}
	}
	const archiveChecksum = createHash('sha256').update(rawArchive).digest('hex');
	await assertCurrentArtifact(repositoryRoot, resolve(repositoryRoot, 'src-tauri/src/ssealed_scaffold_generated.rs'),
		renderGeneratedRust({ version, archiveChecksum }));
	await assertCurrentArtifact(repositoryRoot, resolve(repositoryRoot, 'src/lib/projects/ssealed-scaffold-generated.ts'),
		renderGeneratedTypeScript({ scopes, profiles }));
	return archiveChecksum;
}
